<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/certificate-auth.php';
$pendingUser=fleet_cert_require_user();fleet_cert_require_permission($pendingUser,'page.pending-approvals');
$db=fleet_db();
try{
 $items=[];
 $ops=$db->query("SELECT r.id,r.request_number,r.action_type,r.payload_json,r.request_reason,r.requested_at,u.full_name requester_name,a.primary_identifier FROM operation_change_requests r JOIN users u ON u.id=r.requested_by LEFT JOIN assets a ON a.id=r.asset_id WHERE r.request_status='PENDING'")->fetchAll();
 foreach($ops as $r){$p=json_decode((string)$r['payload_json'],true)?:[];$action=(string)($p['action']??$r['action_type']);$labels=['save_asset'=>!empty($p['id'])?'Update asset':'Create asset','save_yard'=>!empty($p['id'])?'Update location':'Create location','save_driver'=>!empty($p['id'])?'Update driver':'Create driver','set_location'=>'Change asset location','set_status'=>'Change asset status','archive_asset'=>'Archive asset','assign_driver'=>'Assign driver','end_driver'=>'End driver assignment','link_trailer'=>'Link Horse + Trailer'];$subject=$r['primary_identifier']?:($p['primary_identifier']??$p['yard_name']??$p['full_name']??'Fleet record');$detail=match($action){'set_location'=>'Requested location: '.($p['yard_name']??$p['location_name']??$p['yard_id']??'—'),'set_status'=>'Requested status: '.($p['status_name']??$p['status']??$p['status_id']??'—'),'assign_driver'=>'Driver assignment for '.($p['primary_identifier']??'asset #'.($p['asset_id']??'')),'link_trailer'=>($p['head_identifier']??'Horse').' + '.($p['trailer_identifier']??'Trailer'),default=>(string)($r['request_reason']??'')};$items[]=['kind'=>'Fleet operation','title'=>$labels[$action]??str_replace('_',' ',$action),'subject'=>(string)$subject,'detail'=>$detail,'requester'=>(string)$r['requester_name'],'requested_at'=>(string)$r['requested_at'],'reference'=>(string)$r['request_number'],'url'=>'index.php?page=operations-approvals'];}
 $trips=$db->query("SELECT t.id,t.trip_number,t.customer_name,t.cargo_description,t.pickup_location,t.destination,t.requested_at,u.full_name requester_name FROM fleet_trips t JOIN users u ON u.id=t.requested_by WHERE t.status='PENDING'")->fetchAll();
 foreach($trips as $r)$items[]=['kind'=>'Trip','title'=>'Trip request','subject'=>(string)$r['trip_number'].' · '.(string)$r['customer_name'],'detail'=>(string)$r['cargo_description'].' · '.(string)$r['pickup_location'].' → '.(string)$r['destination'],'requester'=>(string)$r['requester_name'],'requested_at'=>(string)$r['requested_at'],'reference'=>(string)$r['trip_number'],'url'=>'index.php?page=operations-approvals'];
 $readiness=$db->query("SELECT r.id,r.request_reason,r.requested_at,h.primary_identifier horse,t.primary_identifier trailer,d.full_name driver,u.full_name requester_name FROM combination_readiness_approvals r JOIN assets h ON h.id=r.horse_asset_id JOIN assets t ON t.id=r.trailer_asset_id JOIN drivers d ON d.id=r.driver_id JOIN users u ON u.id=r.requested_by WHERE r.status='PENDING'")->fetchAll();
 foreach($readiness as $r)$items[]=['kind'=>'Full Truck readiness','title'=>'Combination readiness approval','subject'=>(string)$r['horse'].' + '.(string)$r['trailer'],'detail'=>'Driver: '.(string)$r['driver'].(($r['request_reason']??'')?' · '.(string)$r['request_reason']:''),'requester'=>(string)$r['requester_name'],'requested_at'=>(string)$r['requested_at'],'reference'=>'Readiness #'.(int)$r['id'],'url'=>'index.php?page=operations-approvals'];
 $certs=$db->query("SELECT cs.id,COALESCE(NULLIF(cs.certificate_name,''),ct.display_name) certificate_name,cs.registration_snapshot,cs.asset_scope,cs.expiry_date,cs.submitted_at,u.full_name requester_name FROM certificate_submissions cs JOIN certificate_types ct ON ct.id=cs.certificate_type_id JOIN users u ON u.id=cs.submitted_by WHERE cs.status='PENDING'")->fetchAll();
 foreach($certs as $r)$items[]=['kind'=>'Certificate','title'=>'Certificate submission','subject'=>(string)$r['registration_snapshot'].' · '.(string)$r['certificate_name'],'detail'=>(string)$r['asset_scope'].' · Expiry '.(string)($r['expiry_date']??'not supplied'),'requester'=>(string)$r['requester_name'],'requested_at'=>(string)$r['submitted_at'],'reference'=>'Certificate #'.(int)$r['id'],'url'=>'certificates.php?view=approvals'];
 $changes=$db->query("SELECT ca.id,ca.action,ca.requested_expiry_date,ca.request_reason,ca.requested_at,cs.registration_snapshot,COALESCE(NULLIF(cs.certificate_name,''),ct.display_name) certificate_name,u.full_name requester_name FROM certificate_amendments ca JOIN certificate_submissions cs ON cs.id=ca.certificate_submission_id JOIN certificate_types ct ON ct.id=cs.certificate_type_id JOIN users u ON u.id=ca.requested_by WHERE ca.status='PENDING'")->fetchAll();
 foreach($changes as $r){$title=$r['action']==='UPDATE_EXPIRY'?'Certificate expiry change':'Certificate document removal';$detail=$r['action']==='UPDATE_EXPIRY'?'New expiry: '.(string)$r['requested_expiry_date']:(string)($r['request_reason']??'Removal requested');$items[]=['kind'=>'Certificate change','title'=>$title,'subject'=>(string)$r['registration_snapshot'].' · '.(string)$r['certificate_name'],'detail'=>$detail,'requester'=>(string)$r['requester_name'],'requested_at'=>(string)$r['requested_at'],'reference'=>'Change #'.(int)$r['id'],'url'=>'certificates.php?view=approvals'];}
 $catalog=$db->query("SELECT r.id,r.action,r.requested_at,c.display_name certificate_name,c.sheet_column,u.full_name requester_name FROM certificate_catalog_change_requests r JOIN certificate_catalog c ON c.id=r.certificate_catalog_id JOIN users u ON u.id=r.requested_by WHERE r.status='PENDING'")->fetchAll();
 foreach($catalog as $r)$items[]=['kind'=>'Certificate type','title'=>'Certificate type '.$r['action'],'subject'=>(string)$r['certificate_name'],'detail'=>'Sheet column: '.(string)($r['sheet_column']??'not mapped'),'requester'=>(string)$r['requester_name'],'requested_at'=>(string)$r['requested_at'],'reference'=>'Type request #'.(int)$r['id'],'url'=>'certificates.php?view=approvals'];
 usort($items,static fn(array $a,array $b):int=>strcmp($b['requested_at'],$a['requested_at']));
 json_response(['ok'=>true,'items'=>$items,'total'=>count($items)]);
}catch(Throwable $e){error_log('Pending approvals: '.$e->getMessage());json_response(['ok'=>false,'message'=>'Pending approvals could not be loaded.'],500);}
